-- E-commerce Sales Forecasting & Inventory Analytics (SYNTHETIC data)
-- Table: daily_sales(date, category, orders, units_sold, revenue), generated by analysis.py

-- 1. Daily revenue and units trend (all categories)
SELECT date, SUM(revenue) AS daily_revenue, SUM(units_sold) AS daily_units, SUM(orders) AS daily_orders
FROM daily_sales
GROUP BY date
ORDER BY date;

-- 2. Weekly revenue and units (weeks starting Monday)
SELECT DATE_TRUNC('week', date) AS week_start, SUM(revenue) AS weekly_revenue, SUM(units_sold) AS weekly_units
FROM daily_sales
GROUP BY week_start
ORDER BY week_start;

-- 3. Revenue share by category
SELECT category, SUM(revenue) AS revenue,
       ROUND(100.0 * SUM(revenue) / SUM(SUM(revenue)) OVER (), 2) AS revenue_share_pct,
       SUM(units_sold) AS units
FROM daily_sales
GROUP BY category
ORDER BY revenue DESC;

-- 4. 7-day moving average of daily revenue (smoothing for trend reading)
SELECT date, daily_revenue,
       AVG(daily_revenue) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS revenue_7d_avg
FROM (SELECT date, SUM(revenue) AS daily_revenue FROM daily_sales GROUP BY date) d
ORDER BY date;

-- 5. Inventory inputs per category: average daily demand and demand variability (last 90 days)
SELECT category,
       AVG(day_units) AS avg_daily_demand,
       STDDEV(day_units) AS demand_std
FROM (SELECT date, category, SUM(units_sold) AS day_units
      FROM daily_sales
      WHERE date > (SELECT MAX(date) FROM daily_sales) - INTERVAL '90 days'
      GROUP BY date, category) per_day
GROUP BY category
ORDER BY avg_daily_demand DESC;

-- 6. Reorder point per category: lead-time demand + safety stock
--    lead time = 7 days, service level 95% (z = 1.65): ROP = d*L + z * sigma * SQRT(L)
SELECT category,
       ROUND(avg_daily_demand * 7, 1) AS lead_time_demand,
       ROUND(1.65 * demand_std * SQRT(7), 0) AS safety_stock,
       ROUND(avg_daily_demand * 7 + 1.65 * demand_std * SQRT(7), 0) AS reorder_point
FROM (SELECT category, AVG(day_units) AS avg_daily_demand, STDDEV(day_units) AS demand_std
      FROM (SELECT date, category, SUM(units_sold) AS day_units
            FROM daily_sales
            WHERE date > (SELECT MAX(date) FROM daily_sales) - INTERVAL '90 days'
            GROUP BY date, category) per_day
      GROUP BY category) stats
ORDER BY reorder_point DESC;
